sys_script_include.script:
var ClaudeDiscoveryUtil = Class.create();
ClaudeDiscoveryUtil.prototype = {
    initialize: function() {
        this.constants = new x_agiro_ai_disc_cl.ClaudeDiscoveryConstants();
        this.apiClient = new x_agiro_ai_disc_cl.ClaudeApiClient();
        this._useOobImportSet = this._checkCrossScopeAccess();
    },

    // ========== Discovery Orchestrator ==========

    /**
     * Run full model discovery and load results into CMDB via sn_ai_disc staging.
     * @returns {{ success: boolean, modelsFound: number, message: string }}
     */
    discoverAll: function() {
        var startTime = new Date().getTime();
        var result = { success: false, modelsFound: 0, message: '' };

        try {
            // 1. Discover models
            var models = this.discoverModels();
            result.modelsFound = Object.keys(models).length;

            // 2. Discover tools (skills + connectors)
            var tools = this.discoverTools();
            var toolsFound = Object.keys(tools).length;

            if (result.modelsFound === 0 && toolsFound === 0) {
                result.message = 'No models or tools discovered';
                this._logRun('discovery', 'partial', result.message, 0, 0, 0, startTime);
                return result;
            }

            // 3. Build the sn_ai_disc result DTO
            var discoveryResult = this._buildResultDto(models, {}, tools, {});

            // 4. Load into staging and transform to CMDB
            this._loadToStaging(discoveryResult);

            result.success = true;
            result.message = 'Discovered ' + result.modelsFound + ' models, ' + toolsFound + ' tools';
            this._logRun('discovery', 'success', result.message, result.modelsFound, toolsFound, 0, startTime);

        } catch (e) {
            result.message = 'Discovery failed: ' + e.message;
            gs.error('[ClaudeDiscoveryUtil] ' + result.message);
            this._logRun('discovery', 'error', result.message, result.modelsFound, 0, 0, startTime);
        }

        return result;
    },

    // ========== Usage Logging For Flow ==========

    /**
     * Fetch Enterprise Analytics usage and return agent_usage_logs array
     * matching the shape the OOB "Log AI Usage" subflow expects.
     * Also writes directly to sn_ai_disc_ai_usage as fallback.
     *
     * @param {string} [executionSysId] - execution record to update
     * @returns {{ agent_usage_logs: Array, records_created: number, records_updated: number, records_failed: number, error_message: string }}
     */
    logUsageForFlow: function(executionSysId) {
        var startTime = new Date().getTime();
        var result = {
            agent_usage_logs: [],
            records_created: 0,
            records_updated: 0,
            records_failed: 0,
            error_message: ''
        };

        try {
            var systemSysId = this._ensureClaudeSystem();
            if (!systemSysId) {
                result.error_message = 'Could not create Claude AI Platform system record';
                if (executionSysId) this._updateExecutionRecord(executionSysId, result);
                return result;
            }

            var lagDays = 4;
            var date = this._getDateDaysAgo(lagDays);
            var usageTime = date + ' 00:00:00';

            var page = null;
            var hasMore = true;

            while (hasMore) {
                var response = this.apiClient.getAnalyticsUsers(date, page);
                if (!response.success) {
                    result.error_message = 'Analytics users API failed: ' + response.error;
                    break;
                }

                var data = response.data;
                if (data.data && data.data.length > 0) {
                    for (var i = 0; i < data.data.length; i++) {
                        var userRecord = data.data[i];
                        var email = (userRecord.user && userRecord.user.email_address) || '';

                        // Calculate total activity
                        var count = 0;
                        var chat = userRecord.chat_metrics || {};
                        count += (chat.message_count || 0);
                        var cc = (userRecord.claude_code_metrics && userRecord.claude_code_metrics.core_metrics) || {};
                        count += (cc.distinct_session_count || 0);
                        var cowork = userRecord.cowork_metrics || {};
                        count += (cowork.message_count || 0);
                        count += (userRecord.web_search_count || 0);

                        // Build agent_usage_log matching OOB shape
                        result.agent_usage_logs.push({
                            asset_id: systemSysId,
                            asset_type: 'ai_system',
                            time: usageTime,
                            count: count,
                            session_id: email,
                            user_id: email
                        });

                        // Also write directly to sn_ai_disc_ai_usage
                        var writeResult = this._upsertUsageRecord(systemSysId, userRecord, usageTime);
                        if (writeResult === 'created') result.records_created++;
                        else if (writeResult === 'updated') result.records_updated++;
                        else result.records_failed++;
                    }
                }

                hasMore = data.has_more === true;
                page = data.next_page || null;
            }

            var total = result.records_created + result.records_updated;
            this._logRun('usage', result.error_message ? 'partial' : 'success',
                'Usage: ' + total + ' records (' + result.records_created + ' new, ' + result.records_updated + ' updated)',
                0, 0, total, startTime);

        } catch (e) {
            result.error_message = 'Usage logging failed: ' + e.message;
            gs.error('[ClaudeDiscoveryUtil] ' + result.error_message);
            this._logRun('usage', 'error', result.error_message, 0, 0, 0, startTime);
        }

        if (executionSysId) this._updateExecutionRecord(executionSysId, result);
        return result;
    },

    // ========== Flow Designer Integration ==========

    /**
     * Discover models + tools and return result in the shape the OOB
     * "Discover Data Source" subflow and "Process AI Agents" action expect.
     * Called from Flow Designer, NOT from background scripts.
     * @returns {{ agents: Array, result: string, error_message: string }}
     */
    discoverForFlow: function() {
        var startTime = new Date().getTime();

        try {
            var models = this.discoverModels();
            var tools = this.discoverTools();
            var resultDto = this._buildResultDto(models, {}, tools, {});
            var modelCount = Object.keys(models).length;
            var toolCount = Object.keys(tools).length;

            this._logRun('discovery', 'success',
                'Flow discovery: ' + modelCount + ' models, ' + toolCount + ' tools',
                modelCount, toolCount, 0, startTime);

            return {
                agents: [],
                result: JSON.stringify(resultDto),
                error_message: ''
            };
        } catch (e) {
            var errMsg = 'Claude flow discovery failed: ' + e.message;
            gs.error('[ClaudeDiscoveryUtil] ' + errMsg);
            this._logRun('discovery', 'error', errMsg, 0, 0, 0, startTime);
            return { agents: [], result: '{}', error_message: errMsg };
        }
    },

    /**
     * Full discovery + CMDB write + execution record update.
     * Called from the Flow Designer subflow action step.
     * Replaces the need for the OOB "Process AI Agents" action.
     *
     * @param {string} executionSysId - sys_id of sn_ai_discovery_data_execution record
     * @returns {{ records_created: number, records_updated: number, records_failed: number, error_message: string }}
     */
    discoverAndLoad: function(executionSysId) {
        var startTime = new Date().getTime();
        var counts = { records_created: 0, records_updated: 0, records_failed: 0, error_message: '' };

        try {
            // 1. Discover models + tools
            var models = this.discoverModels();
            var tools = this.discoverTools();
            var result = this._buildResultDto(models, {}, tools, {});

            // 2. Write to CMDB and track counts
            counts = this._loadToCmdbWithCounts(result);

            var modelCount = Object.keys(models).length;
            var toolCount = Object.keys(tools).length;
            this._logRun('discovery', 'success',
                'Created: ' + counts.records_created + ', Updated: ' + counts.records_updated + ', Failed: ' + counts.records_failed,
                modelCount, toolCount, 0, startTime);

        } catch (e) {
            counts.error_message = 'Discovery failed: ' + e.message;
            gs.error('[ClaudeDiscoveryUtil] ' + counts.error_message);
            this._logRun('discovery', 'error', counts.error_message, 0, 0, 0, startTime);
        }

        // 3. Update execution record
        if (executionSysId) {
            this._updateExecutionRecord(executionSysId, counts);
        }

        return counts;
    },

    /**
     * Write to CMDB and return created/updated/failed counts.
     */
    _loadToCmdbWithCounts: function(result) {
        var counts = { records_created: 0, records_updated: 0, records_failed: 0, error_message: '' };

        // Models
        if (!this._modelCategorySysId) {
            this._modelCategorySysId = this._lookupModelCategory('AI model');
        }

        for (var modelId in result.models) {
            if (!result.models.hasOwnProperty(modelId)) continue;
            var model = result.models[modelId];
            try {
                var gr = new GlideRecord('alm_ai_model_digital_asset');
                gr.addQuery('external_ref_id', model.id);
                gr.query();
                var isNew = !gr.next();
                if (isNew) gr.initialize();

                // Ensure manufacturer (core_company) exists
                if (!this._manufacturerSysId) {
                    this._manufacturerSysId = this._ensureManufacturer(this.constants.VENDOR);
                }

                // Ensure cmdb_model (product model) exists for this model
                var productModelSysId = this._ensureProductModel(model);

                gr.setValue('display_name', model.name);
                gr.setValue('external_ref_id', model.id);
                gr.setValue('vendor', model.vendor);
                gr.setValue('install_status', model.install_status);
                gr.setValue('quantity', 1);
                if (this._modelCategorySysId) {
                    gr.setValue('model_category', this._modelCategorySysId);
                }
                if (productModelSysId) {
                    gr.setValue('model', productModelSysId);
                }

                if (isNew) {
                    var newSysId = gr.insert();
                    // display_name can get dropped on insert in scoped apps
                    // re-read and set it explicitly via update
                    if (newSysId) {
                        var updateGr = new GlideRecord('alm_ai_model_digital_asset');
                        if (updateGr.get(newSysId)) {
                            updateGr.setValue('display_name', model.name);
                            updateGr.update();
                        }
                        // Create governance record with "Assess" lifecycle phase
                        this._ensureGovernanceRecord(newSysId);
                    }
                    counts.records_created++;
                } else {
                    gr.update();
                    // Ensure governance record exists for existing assets too
                    this._ensureGovernanceRecord(gr.getUniqueValue());
                    counts.records_updated++;
                }
            } catch (e) {
                counts.records_failed++;
                gs.warn('[ClaudeDiscoveryUtil] Model write failed for ' + model.id + ': ' + e.message);
            }
        }

        // Tools
        for (var toolId in result.tools) {
            if (!result.tools.hasOwnProperty(toolId)) continue;
            var tool = result.tools[toolId];
            try {
                var tGr = new GlideRecord('sn_ent_ai_tool');
                tGr.addQuery('name', tool.name);
                tGr.query();
                var isNewTool = !tGr.next();
                if (isNewTool) tGr.initialize();

                tGr.setValue('name', tool.name);
                tGr.setValue('description', tool.description);
                tGr.setValue('active', tool.active);
                tGr.setValue('type', tool.id.indexOf('connector') > -1 ? 'MCP Connector' : 'Claude Skill');

                if (isNewTool) {
                    tGr.insert();
                    counts.records_created++;
                } else {
                    tGr.update();
                    counts.records_updated++;
                }
            } catch (e) {
                counts.records_failed++;
                gs.warn('[ClaudeDiscoveryUtil] Tool write failed for ' + tool.name + ': ' + e.message);
            }
        }

        return counts;
    },

    /**
     * Ensure a governance record exists for an AI asset.
     *
     * Sets:
     *   - lifecycle_phase = "New" (Intake) — marks asset as pending review
     *   - status = 5 (AI Steward Review) — required for the "Start review"
     *     UI action button to display on the asset form. Without status=5
     *     the AIAssetUtils.canDisplayStartReview() check returns false and
     *     reviewers cannot kick off the assessment playbook.
     *
     * @param {string} assetSysId - sys_id from alm_ai_model_digital_asset or alm_ai_system_digital_asset
     */
    _ensureGovernanceRecord: function(assetSysId) {
        if (!assetSysId) return;
        try {
            // AIAssetUtils.STATUS_AI_STEWARD_REVIEW = 5
            var STATUS_AI_STEWARD_REVIEW = 5;

            // Look up "New" phase sys_id once
            if (!this._assessPhaseSysId) {
                this._assessPhaseSysId = this._lookupLifecyclePhase(this.constants.LIFECYCLE_PHASE_NEW_ASSET);
            }

            var gr = new GlideRecord('sn_ai_governance_asset_governance_details');
            gr.addQuery('asset', assetSysId);
            gr.setLimit(1);
            gr.query();

            if (gr.next()) {
                // Existing record — backfill phase and/or status if missing so
                // previously-discovered assets get the Start review button too.
                var dirty = false;
                if (!gr.getValue('lifecycle_phase') && this._assessPhaseSysId) {
                    gr.setValue('lifecycle_phase', this._assessPhaseSysId);
                    dirty = true;
                }
                if (!gr.getValue('status')) {
                    gr.setValue('status', STATUS_AI_STEWARD_REVIEW);
                    dirty = true;
                }
                if (dirty) gr.update();
                return;
            }

            // Create new governance record
            gr.initialize();
            gr.setValue('asset', assetSysId);
            if (this._assessPhaseSysId) {
                gr.setValue('lifecycle_phase', this._assessPhaseSysId);
            }
            gr.setValue('status', STATUS_AI_STEWARD_REVIEW);
            gr.insert();
        } catch (e) {
            gs.warn('[ClaudeDiscoveryUtil] Governance record creation failed for ' + assetSysId + ': ' + e.message);
        }
    },

    /**
     * Look up a lifecycle phase sys_id by name.
     * @param {string} name - e.g. 'Assess', 'Deploy'
     * @returns {string|null}
     */
    _lookupLifecyclePhase: function(name) {
        var gr = new GlideRecord('sn_ai_governance_lifecycle');
        gr.addQuery('name', name);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) return gr.getUniqueValue();
        gs.warn('[ClaudeDiscoveryUtil] Lifecycle phase not found: ' + name);
        return null;
    },

    /**
     * Update the sn_ai_discovery_data_execution record with results.
     */
    _updateExecutionRecord: function(executionSysId, counts) {
        var gr = new GlideRecord('sn_ai_discovery_data_execution');
        if (gr.get(executionSysId)) {
            gr.setValue('state', counts.error_message ? 'failed' : 'successful');
            gr.setValue('records_created', counts.records_created);
            gr.setValue('records_updated', counts.records_updated);
            gr.setValue('records_failed', counts.records_failed);
            gr.setValue('error_message', counts.error_message || '');
            gr.setValue('last_execution_time', new GlideDateTime());
            gr.update();
        }
    },

    // ========== Usage Logging ==========

    /**
     * Fetch Enterprise Analytics per-user activity and log to sn_ai_disc_ai_usage.
     * Creates a "Claude AI Platform" system record if it doesn't exist.
     * Each user's daily total activity becomes one usage record.
     *
     * @param {string} [executionSysId] - optional execution record to update
     * @returns {{ records_created: number, records_updated: number, error_message: string }}
     */
    logUsage: function(executionSysId) {
        var startTime = new Date().getTime();
        var counts = { records_created: 0, records_updated: 0, records_failed: 0, error_message: '' };

        try {
            // Ensure the Claude AI Platform system record exists
            var systemSysId = this._ensureClaudeSystem();
            if (!systemSysId) {
                counts.error_message = 'Could not create Claude AI Platform system record';
                this._logRun('usage', 'error', counts.error_message, 0, 0, 0, startTime);
                if (executionSysId) this._updateExecutionRecord(executionSysId, counts);
                return counts;
            }

            // Fetch per-user analytics (3+ days ago due to data lag)
            var lagDays = 4;
            var date = this._getDateDaysAgo(lagDays);
            var usageTime = date + ' 00:00:00';

            var page = null;
            var hasMore = true;

            while (hasMore) {
                var response = this.apiClient.getAnalyticsUsers(date, page);
                if (!response.success) {
                    counts.error_message = 'Analytics users API failed: ' + response.error;
                    gs.warn('[ClaudeDiscoveryUtil] ' + counts.error_message);
                    break;
                }

                var data = response.data;
                if (data.data && data.data.length > 0) {
                    for (var i = 0; i < data.data.length; i++) {
                        var userRecord = data.data[i];
                        var result = this._upsertUsageRecord(systemSysId, userRecord, usageTime);
                        if (result === 'created') counts.records_created++;
                        else if (result === 'updated') counts.records_updated++;
                        else counts.records_failed++;
                    }
                }

                hasMore = data.has_more === true;
                page = data.next_page || null;
            }

            var total = counts.records_created + counts.records_updated;
            this._logRun('usage', counts.error_message ? 'partial' : 'success',
                'Usage: ' + total + ' records (' + counts.records_created + ' new, ' + counts.records_updated + ' updated)',
                0, 0, total, startTime);

        } catch (e) {
            counts.error_message = 'Usage logging failed: ' + e.message;
            gs.error('[ClaudeDiscoveryUtil] ' + counts.error_message);
            this._logRun('usage', 'error', counts.error_message, 0, 0, 0, startTime);
        }

        if (executionSysId) this._updateExecutionRecord(executionSysId, counts);
        return counts;
    },

    /**
     * Upsert a single usage record from Enterprise Analytics user data.
     * Calculates total activity count across all channels.
     */
    _upsertUsageRecord: function(systemSysId, userRecord, usageTime) {
        try {
            var email = '';
            if (userRecord.user) {
                email = userRecord.user.email_address || '';
            }

            // Calculate total activity count
            var count = 0;
            var chat = userRecord.chat_metrics || {};
            count += (chat.message_count || 0);

            var cc = (userRecord.claude_code_metrics && userRecord.claude_code_metrics.core_metrics) || {};
            count += (cc.distinct_session_count || 0);

            var cowork = userRecord.cowork_metrics || {};
            count += (cowork.message_count || 0);

            count += (userRecord.web_search_count || 0);

            // Look up ServiceNow user by email
            var userSysId = this._lookupUser(email);

            // Upsert: match on ai_system + time + user (or session_id for email)
            var gr = new GlideRecord('sn_ai_disc_ai_usage');
            gr.addQuery('ai_system', systemSysId);
            gr.addQuery('time', usageTime);
            if (userSysId) {
                gr.addQuery('user', userSysId);
            } else {
                gr.addQuery('session_id', email);
            }
            gr.query();

            var isNew = !gr.next();
            if (isNew) gr.initialize();

            gr.setValue('ai_system', systemSysId);
            gr.setValue('count', count);
            gr.setValue('time', usageTime);
            gr.setValue('type', 'daily_activity');
            if (userSysId) {
                gr.setValue('user', userSysId);
            }
            gr.setValue('session_id', email);

            if (isNew) {
                gr.insert();
                return 'created';
            } else {
                gr.update();
                return 'updated';
            }
        } catch (e) {
            gs.warn('[ClaudeDiscoveryUtil] Usage record failed for ' + (email || 'unknown') + ': ' + e.message);
            return 'failed';
        }
    },

    /**
     * Find or create the "Claude AI Platform" system record on alm_ai_system_digital_asset.
     */
    _ensureClaudeSystem: function() {
        if (this._claudeSystemSysId) return this._claudeSystemSysId;

        var gr = new GlideRecord('alm_ai_system_digital_asset');
        gr.addQuery('display_name', 'Claude AI Platform');
        gr.addQuery('vendor', this.constants.VENDOR);
        gr.query();

        if (gr.next()) {
            this._claudeSystemSysId = gr.getUniqueValue();
            return this._claudeSystemSysId;
        }

        // Create it
        gr.initialize();
        gr.setValue('display_name', 'Claude AI Platform');
        gr.setValue('vendor', this.constants.VENDOR);
        gr.setValue('install_status', this.constants.INSTALL_STATUS.DEPLOYED);
        gr.setValue('quantity', 1);
        var sysId = gr.insert();

        // display_name may get dropped on insert from scoped app
        if (sysId) {
            var updateGr = new GlideRecord('alm_ai_system_digital_asset');
            if (updateGr.get(sysId)) {
                updateGr.setValue('display_name', 'Claude AI Platform');
                updateGr.update();
            }
            // Create governance record with "Assess" lifecycle phase
            this._ensureGovernanceRecord(sysId);
        }

        gs.info('[ClaudeDiscoveryUtil] Created Claude AI Platform system: ' + sysId);
        this._claudeSystemSysId = sysId;
        return sysId;
    },

    /**
     * Look up a sys_user by email address.
     * @returns {string|null} sys_id of the user, or null
     */
    _lookupUser: function(email) {
        if (!email) return null;
        if (!this._userCache) this._userCache = {};
        if (this._userCache[email] !== undefined) return this._userCache[email];

        var gr = new GlideRecord('sys_user');
        gr.addQuery('email', email);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) {
            this._userCache[email] = gr.getUniqueValue();
            return this._userCache[email];
        }
        this._userCache[email] = null;
        return null;
    },

    // ========== Model Discovery ==========

    /**
     * Discover Claude models from the hardcoded catalog, enriched with
     * actually-used models from the messages usage API.
     * @returns {object} Map of model id -> model DTO
     */
    discoverModels: function() {
        var models = {};

        // Start with the known model catalog
        var catalog = this.constants.MODEL_CATALOG;
        for (var i = 0; i < catalog.length; i++) {
            var cm = catalog[i];
            models[cm.id] = this._buildModelDto(cm.id, cm.name, cm.version, cm.description);
        }

        // Enrich with models seen in usage data (catches new models not in catalog)
        this._enrichModelsFromUsage(models);

        gs.info('[ClaudeDiscoveryUtil] Discovered ' + Object.keys(models).length + ' models');
        return models;
    },

    /**
     * Check messages usage API for models actually being used.
     * Any model found in usage that isn't in the catalog gets added.
     */
    _enrichModelsFromUsage: function(models) {
        try {
            var yesterday = this._getYesterdayISO();
            var response = this.apiClient.getMessagesUsage(yesterday, null, '1d');

            if (!response.success) {
                gs.warn('[ClaudeDiscoveryUtil] Could not enrich models from usage: ' + response.error);
                return;
            }

            var data = response.data;
            if (!data.data) return;

            for (var i = 0; i < data.data.length; i++) {
                var bucket = data.data[i];
                if (!bucket.results) continue;

                for (var j = 0; j < bucket.results.length; j++) {
                    var modelId = bucket.results[j].model;
                    if (modelId && !models[modelId]) {
                        models[modelId] = this._buildModelDto(
                            modelId,
                            this._formatModelName(modelId),
                            this._extractVersion(modelId),
                            'Discovered from usage data'
                        );
                        gs.info('[ClaudeDiscoveryUtil] Found new model from usage: ' + modelId);
                    }
                }
            }
        } catch (e) {
            gs.warn('[ClaudeDiscoveryUtil] Usage enrichment error: ' + e.message);
        }
    },

    // ========== Tool Discovery (Skills + Connectors) ==========

    /**
     * Discover tools from Enterprise Analytics API.
     * Skills and MCP connectors both map to sn_ent_ai_tool.
     * Requires Enterprise plan + analytics API key configured.
     * @returns {object} Map of tool id -> tool DTO
     */
    discoverTools: function() {
        var tools = {};

        var analyticsEnabled = gs.getProperty(this.constants.PROPERTY.ANALYTICS_ENABLED) === 'true';
        if (!analyticsEnabled) {
            gs.info('[ClaudeDiscoveryUtil] Analytics not enabled, skipping tool discovery');
            return tools;
        }

        var lagDays = 4;
        var date = this._getDateDaysAgo(lagDays);

        // Discover skills
        this._discoverSkills(tools, date);

        // Discover connectors
        this._discoverConnectors(tools, date);

        gs.info('[ClaudeDiscoveryUtil] Discovered ' + Object.keys(tools).length + ' tools (skills + connectors)');
        return tools;
    },

    /**
     * Fetch skills from Enterprise Analytics and add to tools map.
     */
    _discoverSkills: function(tools, date) {
        try {
            var page = null;
            var hasMore = true;

            while (hasMore) {
                var response = this.apiClient.getAnalyticsSkills(date, page);
                if (!response.success) {
                    gs.warn('[ClaudeDiscoveryUtil] Skills API failed: ' + response.error);
                    return;
                }

                var data = response.data;
                if (data.data && data.data.length > 0) {
                    for (var i = 0; i < data.data.length; i++) {
                        var skill = data.data[i];
                        var skillId = 'claude-skill-' + skill.skill_name;
                        tools[skillId] = this._buildToolDto(
                            skillId,
                            skill.skill_name,
                            'Claude Skill',
                            true
                        );
                    }
                }

                hasMore = data.has_more === true;
                page = data.next_page || null;
            }
        } catch (e) {
            gs.warn('[ClaudeDiscoveryUtil] Skills discovery error: ' + e.message);
        }
    },

    /**
     * Fetch MCP connectors from Enterprise Analytics and add to tools map.
     */
    _discoverConnectors: function(tools, date) {
        try {
            var page = null;
            var hasMore = true;

            while (hasMore) {
                var response = this.apiClient.getAnalyticsConnectors(date, page);
                if (!response.success) {
                    gs.warn('[ClaudeDiscoveryUtil] Connectors API failed: ' + response.error);
                    return;
                }

                var data = response.data;
                if (data.data && data.data.length > 0) {
                    for (var i = 0; i < data.data.length; i++) {
                        var connector = data.data[i];
                        var connectorId = 'claude-connector-' + connector.connector_name;
                        tools[connectorId] = this._buildToolDto(
                            connectorId,
                            connector.connector_name,
                            'MCP Connector',
                            true
                        );
                    }
                }

                hasMore = data.has_more === true;
                page = data.next_page || null;
            }
        } catch (e) {
            gs.warn('[ClaudeDiscoveryUtil] Connectors discovery error: ' + e.message);
        }
    },

    // ========== DTO Builders ==========

    /**
     * Build a model DTO matching the sn_ai_disc initializeModelsObject() shape.
     */
    _buildModelDto: function(id, name, version, description) {
        return {
            id: id,
            name: name,
            version: version || '',
            description: description || '',
            short_description: description || '',
            vendor: this.constants.VENDOR,
            manufacturer: this.constants.MANUFACTURER,
            install_status: String(this.constants.INSTALL_STATUS.DEPLOYED),
        };
    },

    /**
     * Build a tool DTO matching the sn_ai_disc initializeToolsObject() shape.
     * Maps to sn_ent_ai_tool in CMDB.
     */
    _buildToolDto: function(id, name, description, active) {
        return {
            id: id,
            name: name,
            description: description || '',
            vendor: this.constants.VENDOR,
            active: active !== false,
        };
    },

    /**
     * Build the top-level result DTO expected by sn_ai_disc.AiDiscoveryImportSetUtil.
     */
    _buildResultDto: function(models, agents, tools, prompts) {
        return {
            models: models,
            agents: agents || {},
            tools: tools || {},
            prompts: prompts || {},
            agent_subcomponent_m2m: [],
            additional_attributes: [],
        };
    },

    // ========== Staging / Import Set Loading ==========

    /**
     * Load discovery results into sn_ai_disc staging tables.
     * Tries OOB AiDiscoveryImportSetUtil first; falls back to direct staging writes.
     */
    _loadToStaging: function(result) {
        if (this._useOobImportSet) {
            this._loadViaOobImportSetUtil(result);
        } else if (this._hasStagingTables()) {
            this._loadDirectToStaging(result);
        } else {
            this._loadDirectToCmdb(result);
        }
    },

    /**
     * Use the OOB sn_ai_disc.AiDiscoveryImportSetUtil to load and transform.
     */
    _loadViaOobImportSetUtil: function(result) {
        try {
            var importSetUtil = new sn_ai_disc.AiDiscoveryImportSetUtil();
            var importResult = importSetUtil.transformAIAssetImportSet(result, this.constants.SOURCE_NAME);
            gs.info('[ClaudeDiscoveryUtil] OOB import set transform complete: ' + JSON.stringify(importResult));
        } catch (e) {
            gs.warn('[ClaudeDiscoveryUtil] OOB ImportSetUtil failed, falling back to direct load: ' + e.message);
            this._useOobImportSet = false;
            this._loadDirectToStaging(result);
        }
    },

    /**
     * Fallback: write directly to sn_ai_disc staging tables and trigger transform.
     */
    _loadDirectToStaging: function(result) {
        var stagingTable = 'sn_ai_disc_ai_model_asset_staging';

        // Create an import set record
        var importSetGr = new GlideRecord('sys_import_set');
        importSetGr.initialize();
        importSetGr.setValue('table_name', stagingTable);
        importSetGr.setValue('state', 'loading');
        importSetGr.setValue('mode', 'asynchronous');
        var importSetSysId = importSetGr.insert();

        if (!importSetSysId) {
            gs.error('[ClaudeDiscoveryUtil] Failed to create import set');
            return;
        }

        // Load model records into staging
        var modelCount = 0;
        for (var modelId in result.models) {
            if (!result.models.hasOwnProperty(modelId)) continue;
            var model = result.models[modelId];

            var stagingGr = new GlideRecord(stagingTable);
            stagingGr.initialize();
            stagingGr.setValue('u_id', model.id);
            stagingGr.setValue('u_name', model.name);
            stagingGr.setValue('u_version', model.version);
            stagingGr.setValue('u_description', model.description);
            stagingGr.setValue('u_short_description', model.short_description);
            stagingGr.setValue('u_vendor', model.vendor);
            stagingGr.setValue('u_manufacturer', model.manufacturer);
            stagingGr.setValue('u_install_status', model.install_status);
            stagingGr.setValue('sys_import_set', importSetSysId);
            stagingGr.insert();
            modelCount++;
        }

        // Mark import set as loaded
        importSetGr.get(importSetSysId);
        importSetGr.setValue('state', 'loaded');
        importSetGr.update();

        // Trigger transform
        var transformer = new GlideImportSetTransformer();
        transformer.transformAllMaps(importSetSysId);

        gs.info('[ClaudeDiscoveryUtil] Direct staging load complete: ' + modelCount + ' models, import set ' + importSetSysId);
    },

    /**
     * Write models and tools directly to CMDB tables, bypassing staging.
     * Used when sn_ai_disc v2 staging tables don't exist (v1.1.x instances).
     */
    _loadDirectToCmdb: function(result) {
        var modelCount = 0;
        var toolCount = 0;

        // Upsert models to alm_ai_model_digital_asset
        // Field mapping (v1.1.x schema):
        //   display_name (not 'name'), vendor, install_status, external_ref_id
        for (var modelId in result.models) {
            if (!result.models.hasOwnProperty(modelId)) continue;
            var model = result.models[modelId];

            var gr = new GlideRecord('alm_ai_model_digital_asset');
            gr.addQuery('external_ref_id', model.id);
            gr.query();

            if (!gr.next()) {
                gr.initialize();
            }

            gr.setValue('display_name', model.name);
            gr.setValue('external_ref_id', model.id);
            gr.setValue('vendor', model.vendor);
            gr.setValue('install_status', model.install_status);
            // model_category: "AI model" — look up sys_id dynamically
            if (!this._modelCategorySysId) {
                this._modelCategorySysId = this._lookupModelCategory('AI model');
            }
            if (this._modelCategorySysId) {
                gr.setValue('model_category', this._modelCategorySysId);
            }
            gr.setValue('quantity', 1);
            gr.update() || gr.insert();
            modelCount++;
        }

        // Upsert tools to sn_ent_ai_tool
        // Field mapping (v1.1.x schema):
        //   name, description, type, active (no 'vendor' field)
        for (var toolId in result.tools) {
            if (!result.tools.hasOwnProperty(toolId)) continue;
            var tool = result.tools[toolId];

            var tGr = new GlideRecord('sn_ent_ai_tool');
            tGr.addQuery('name', tool.name);
            tGr.query();

            if (!tGr.next()) {
                tGr.initialize();
            }

            tGr.setValue('name', tool.name);
            tGr.setValue('description', tool.description);
            tGr.setValue('active', tool.active);
            tGr.setValue('type', tool.id.indexOf('connector') > -1 ? 'MCP Connector' : 'Claude Skill');
            tGr.update() || tGr.insert();
            toolCount++;
        }

        gs.info('[ClaudeDiscoveryUtil] Direct CMDB write: ' + modelCount + ' models, ' + toolCount + ' tools');
    },

    /**
     * Check if sn_ai_disc v2 staging tables exist.
     */
    _hasStagingTables: function() {
        var gr = new GlideRecord('sn_ai_disc_ai_model_asset_staging');
        return gr.isValid();
    },

    // ========== Cross-Scope Access Check ==========

    /**
     * Check if we can access sn_ai_disc.AiDiscoveryImportSetUtil.
     * @returns {boolean}
     */
    _checkCrossScopeAccess: function() {
        try {
            if (typeof sn_ai_disc !== 'undefined' && sn_ai_disc.AiDiscoveryImportSetUtil) {
                return true;
            }
        } catch (e) {
            // Cross-scope access denied
        }
        gs.info('[ClaudeDiscoveryUtil] sn_ai_disc cross-scope access not available, will use direct staging');
        return false;
    },

    // ========== Run Log ==========

    /**
     * Write a record to the discovery run log.
     */
    _logRun: function(runType, status, message, modelsFound, toolsFound, usageRecords, startTime) {
        var duration = new Date().getTime() - startTime;

        try {
            var gr = new GlideRecord(this.constants.RUN_LOG_TABLE);
            if (!gr.isValid()) {
                gs.info('[ClaudeDiscoveryUtil] Run log table not found, skipping log');
                return;
            }
            gr.initialize();
            gr.setValue('x_agiro_ai_disc_cl_run_type', runType);
            gr.setValue('x_agiro_ai_disc_cl_status', status);
            gr.setValue('x_agiro_ai_disc_cl_message', (message || '').substring(0, 4000));
            gr.setValue('x_agiro_ai_disc_cl_models_found', modelsFound || 0);
            gr.setValue('x_agiro_ai_disc_cl_tools_found', toolsFound || 0);
            gr.setValue('x_agiro_ai_disc_cl_usage_records', usageRecords || 0);
            gr.setValue('x_agiro_ai_disc_cl_duration_ms', duration);
            gr.insert();
        } catch (e) {
            gs.warn('[ClaudeDiscoveryUtil] Could not write to run log: ' + e.message);
        }
    },

    // ========== Utility ==========

    /**
     * Get yesterday's date as an ISO 8601 string (YYYY-MM-DDT00:00:00Z).
     */
    _getYesterdayISO: function() {
        var gdt = new GlideDateTime();
        gdt.addDaysUTC(-1);
        return gdt.getValue().substring(0, 10) + 'T00:00:00Z';
    },

    /**
     * Find or create the manufacturer (core_company) record.
     * @param {string} name - e.g. 'Anthropic'
     * @returns {string|null} sys_id of the core_company record
     */
    _ensureManufacturer: function(name) {
        var gr = new GlideRecord('core_company');
        gr.addQuery('name', name);
        gr.addQuery('manufacturer', true);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) return gr.getUniqueValue();

        // Create it
        gr.initialize();
        gr.setValue('name', name);
        gr.setValue('manufacturer', true);
        var sysId = gr.insert();
        gs.info('[ClaudeDiscoveryUtil] Created manufacturer: ' + name + ' (' + sysId + ')');
        return sysId;
    },

    /**
     * Find or create a cmdb_ai_model_product_model record for a Claude model.
     * This is the product model that the digital asset references.
     * @param {object} model - model DTO with id, name, vendor, etc.
     * @returns {string|null} sys_id of the cmdb_model record
     */
    _ensureProductModel: function(model) {
        // Check if it exists by name + manufacturer
        var gr = new GlideRecord('cmdb_ai_model_product_model');
        gr.addQuery('name', model.name);
        gr.addQuery('manufacturer', this._manufacturerSysId);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) return gr.getUniqueValue();

        // Create it
        gr.initialize();
        gr.setValue('name', model.name);
        gr.setValue('manufacturer', this._manufacturerSysId);
        if (this._modelCategorySysId) {
            gr.setValue('cmdb_model_category', this._modelCategorySysId);
        }
        gr.setValue('sys_class_name', 'cmdb_ai_model_product_model');
        var sysId = gr.insert();
        gs.info('[ClaudeDiscoveryUtil] Created product model: ' + model.name + ' (' + sysId + ')');
        return sysId;
    },

    /**
     * Look up the sys_id of a model_category by name.
     * @param {string} categoryName - e.g. 'AI model'
     * @returns {string|null} sys_id of the cmdb_model_category record
     */
    _lookupModelCategory: function(categoryName) {
        var gr = new GlideRecord('cmdb_model_category');
        gr.addQuery('name', categoryName);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) return gr.getUniqueValue();
        gs.warn('[ClaudeDiscoveryUtil] Model category not found: ' + categoryName);
        return null;
    },

    /**
     * Get a date N days ago as YYYY-MM-DD string.
     * @param {number} days - Number of days to go back
     * @returns {string} Date in YYYY-MM-DD format
     */
    _getDateDaysAgo: function(days) {
        var gdt = new GlideDateTime();
        gdt.addDaysUTC(-1 * days);
        return gdt.getValue().substring(0, 10);
    },

    /**
     * Format a model ID into a human-readable name.
     * e.g. 'claude-3-5-sonnet-20241022' -> 'Claude 3.5 Sonnet'
     */
    _formatModelName: function(modelId) {
        if (!modelId) return '';

        // Remove date suffix (e.g. -20241022)
        var name = modelId.replace(/-\d{8}$/, '');

        // Replace hyphens with spaces and capitalise
        var parts = name.split('-');
        for (var i = 0; i < parts.length; i++) {
            parts[i] = parts[i].charAt(0).toUpperCase() + parts[i].substring(1);
        }

        // Rejoin, fixing version numbers like "3 5" -> "3.5"
        var result = parts.join(' ');
        result = result.replace(/(\d) (\d)/g, '$1.$2');

        return result;
    },

    /**
     * Extract a version string from a model ID.
     * e.g. 'claude-3-5-sonnet-20241022' -> '3.5'
     */
    _extractVersion: function(modelId) {
        if (!modelId) return '';
        var match = modelId.match(/claude-(\d+(?:-\d+)?)/);
        if (match) {
            return match[1].replace('-', '.');
        }
        return '';
    },

    type: 'ClaudeDiscoveryUtil'
};
